-- 合成コーパス（捏造名・捏造13桁番号）。build-fixture が生成。手編集しない。
-- name_normalized / name_no_kind は @houjin/normalizer 由来で production 照合と一致する。

BEGIN;
-- ガード: ベンチマーク専用DB以外への誤適用で TRUNCATE が共有データを消さないよう、
-- (a) 空DB または (b) 適用済みマーカーがあり、かつ既存行がすべて本fixtureの捏造番号
-- 帯域（9000000000001〜9000000002000）に収まる場合だけ適用を許可する。マーカーは
-- 「過去に適用した」ことしか示さないため、その後に実データが同期されたDBを守るには
-- 既存行の帯域再検証が必須。
-- 検証と TRUNCATE の間に並行同期のコミットが割り込む TOCTOU を防ぐため、
-- 検証前にテーブルロックを取得して置換全体を原子化する。
-- 誤って稼働中の共有DBへ流した場合にロック待ち自体が corporations を塞がないよう、
-- 待機は短時間で諦めて即エラーにする（このガードの想定誤用シナリオ）。
SET LOCAL lock_timeout = '3s';
LOCK TABLE corporations IN ACCESS EXCLUSIVE MODE;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM corporations LIMIT 1) THEN
    IF to_regclass('public.benchmark_fixture_marker') IS NULL THEN
      RAISE EXCEPTION 'refusing to truncate: corporations has data and this is not a marked benchmark database';
    END IF;
    IF EXISTS (
      SELECT 1 FROM corporations
       WHERE corporate_number NOT BETWEEN '9000000000001' AND '9000000002000'
       LIMIT 1
    ) THEN
      RAISE EXCEPTION 'refusing to truncate: corporations contains rows outside the benchmark fixture range (real data may have been synced since the last seed)';
    END IF;
  END IF;
END $$;
CREATE TABLE IF NOT EXISTS benchmark_fixture_marker ();
-- リポジトリの全publicテーブル deny-all RLS 不変条件（verify_schema が検査）に従う。
ALTER TABLE benchmark_fixture_marker ENABLE ROW LEVEL SECURITY;
TRUNCATE corporations;

